// Replaces the header that swagger-typescript-api writes at the top of every
// generated API class with a one-line notice. Fails when a file does not start
// with exactly the known upstream header, so that a changed header is noticed
// instead of silently eating code.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const upstreamHeader = [
  '/* eslint-disable */',
  '/* tslint:disable */',
  '// @ts-nocheck',
  '/*',
  ' * ---------------------------------------------------------------',
  ' * ## THIS FILE WAS GENERATED VIA SWAGGER-TYPESCRIPT-API        ##',
  ' * ##                                                           ##',
  ' * ## AUTHOR: acacode                                           ##',
  ' * ## SOURCE: https://github.com/acacode/swagger-typescript-api ##',
  ' * ---------------------------------------------------------------',
  ' */',
  ''
].join('\n');

const notice = '// Generated by the web-api-client:generate target from apps/server/openapi.json. Do not edit.\n';

/** Returns the file content with the upstream header replaced; throws when it is not there. */
export function replaceHeader(source, name) {
  if (!source.startsWith(upstreamHeader)) {
    throw new Error(`${name}: does not start with the known swagger-typescript-api header; update scripts/replace-header.mjs`);
  }
  return notice + source.slice(upstreamHeader.length);
}

export function replaceHeaders(dir) {
  const files = readdirSync(dir).filter(f => /^[A-Z].*\.ts$/.test(f) && !f.endsWith('.spec.ts'));
  if (files.length === 0) {
    throw new Error(`${dir}: no generated API classes found`);
  }
  for (const file of files) {
    const path = join(dir, file);
    writeFileSync(path, replaceHeader(readFileSync(path, 'utf8'), file));
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const dir = process.argv[2];
  if (!dir) {
    console.error('usage: replace-header.mjs <generated-dir>');
    process.exit(2);
  }
  try {
    replaceHeaders(dir);
  } catch (error) {
    console.error(error.message);
    process.exit(1);
  }
}
